CREATE ROLE greenhouse_runtime; CREATE SCHEMA greenhouse_growth; CREATE SCHEMA greenhouse_core;
CREATE TABLE greenhouse_growth.grader_profiles (profile_id text,public_id text,brand_name text,website_url text,market text,locale text,category text,competitors_declared text[],status text,created_at timestamp with time zone,updated_at timestamp with time zone,organization_id text,recurring_regrade_enabled boolean,recurring_regrade_cadence text,recurring_regrade_next_at timestamp with time zone,recurring_regrade_last_run_id text,recurring_regrade_last_at timestamp with time zone,category_node_id text,category_label text,category_confidence numeric,category_source text,business_model text,business_model_confidence numeric,business_model_source text, PRIMARY KEY (profile_id));
CREATE TABLE greenhouse_growth.grader_prompt_sets (set_id text,profile_id text,version integer,business_model text,category_node_id text,prompts_json jsonb,generation_strategy text,model text,system_prompt_version text,grounding_sources_json jsonb,status text,created_by text,approved_by text,approved_at timestamp with time zone,created_at timestamp with time zone,updated_at timestamp with time zone, PRIMARY KEY (set_id));
CREATE TABLE greenhouse_growth.grader_runs (run_id text,public_id text,profile_id text,run_kind text,mode text,status text,provider_policy_version text,prompt_pack_version text,requested_providers text[],idempotency_key text,estimated_cost_usd numeric,cost_ceiling_usd numeric,started_at timestamp with time zone,finished_at timestamp with time zone,created_at timestamp with time zone,execution_prompts jsonb,poll_token text,public_delivery_state text,organization_id text,assignment_id text,run_source text,cost_attribution text,prompt_set_id text,prompt_set_version integer, PRIMARY KEY (run_id));
CREATE TABLE greenhouse_growth.provider_observations(observation_id text PRIMARY KEY);
CREATE TABLE greenhouse_core.capabilities_registry(capability_key text PRIMARY KEY,module text,allowed_actions text[],allowed_scopes text[],description text,introduced_at timestamptz,deprecated_at timestamptz);
CREATE UNIQUE INDEX grader_prompt_sets_one_active_per_profile_idx ON greenhouse_growth.grader_prompt_sets(profile_id) WHERE status='active';
